import{_ as t,c as a,o as r,ah as l}from"./chunks/framework.PvdZnrZd.js";const b=JSON.parse('{"title":"SELLER TAGS AND CATEGORIES","description":"SELLER TAGS AND CATEGORIES","frontmatter":{"title":"SELLER TAGS AND CATEGORIES","description":"SELLER TAGS AND CATEGORIES","date":"2025-07-29T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/featured-app/seller-add-ons/seller-tags-and-categories.md","filePath":"zenith/featured-app/seller-add-ons/seller-tags-and-categories.md"}'),o={name:"zenith/featured-app/seller-add-ons/seller-tags-and-categories.md"};function n(s,e,g,p,d,i){return r(),a("div",null,[...e[0]||(e[0]=[l('<p>The <a href="/zenith/introduction/">Multivendor Marketplace App for Shopify</a> is up with another most requested add-on by the name <strong>Seller Tags &amp; Categories</strong>.</p><p><strong>Purpose of the app</strong>: Using this featured app, the vendors will be able to choose tags &amp; categories for themselves added by the admin. Further, these can be used as filters on the storefront.</p><p><strong>CHARGES</strong>:</p><p>This feature will have an additional charge of <strong>USD 5 per month</strong> over &amp; above your current Multivendor Marketplace plan.</p><h2 id="enabling-the-featured-app" tabindex="-1">Enabling the featured app <a class="header-anchor" href="#enabling-the-featured-app" aria-label="Permalink to &quot;Enabling the featured app&quot;">​</a></h2><p>Enable the following app by visiting:</p><ul><li>Multi-Vendor <strong>Admin Panel</strong></li><li>From the Dashboard, hover over the <strong>three dots</strong> on the top-right of the page</li><li>Click on <strong>Feature Apps</strong></li><li>Search for the app &amp; click on ‘<strong>Enable</strong>‘</li><li>After accepting the charges, you’ll be good to configure the app!</li></ul><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/11/sellertag1.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/11/sellertag1.webp" alt="image-82"></a></p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The admin needs to visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Sellers Configuration</strong>. Configure the following tabs as per your requirement:</p><ul><li>Allow seller to add tags to their account</li><li>Restrict seller to add tags at the seller signup page</li><li>Allow seller to add categories to their account</li><li>Restrict seller to add categories at the seller signup page</li></ul><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory7.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory7.webp" alt="image-21"></a></p><h2 id="seller-tags" tabindex="-1">Seller Tags <a class="header-anchor" href="#seller-tags" aria-label="Permalink to &quot;Seller Tags&quot;">​</a></h2><p>Now, to add seller tags, the admin needs to visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Sellers</strong> &gt; <strong>Seller Tags</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/11/sellertag3.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/11/sellertag3.webp" alt="image-20"></a></p><p>Further, clicking on <strong>Add Tag</strong>, the seller tags can be added.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/11/sellertag4.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/11/sellertag4.webp" alt="image-22"></a></p><p>The seller tag can be deleted, edited or disabled:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory6.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory6.webp" alt="image-23"></a></p><h2 id="seller-category" tabindex="-1">Seller Category <a class="header-anchor" href="#seller-category" aria-label="Permalink to &quot;Seller Category&quot;">​</a></h2><p>To add seller category, the admin needs to visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Sellers</strong> &gt; <strong>Seller Collection</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory5.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory5.webp" alt="image-24"></a></p><p>Further, the category can be added by clicking on <strong>Add Collection</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory4.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory4.webp" alt="image-25"></a></p><p>Added category can now be delete or edited:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory3.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory3.webp" alt="image-26"></a></p><p>The admin can add tags and categories for a seller by visiting edit seller page:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory2.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory2.webp" alt="image-33"></a></p><h2 id="seller-panel" tabindex="-1">Seller Panel <a class="header-anchor" href="#seller-panel" aria-label="Permalink to &quot;Seller Panel&quot;">​</a></h2><p>The sellers can choose the <strong>seller category</strong> &amp; <strong>seller tags</strong> added by the admin by visiting <strong>Multivendor Seller Panel</strong> &gt; <strong>Profile</strong> &gt; <strong>My Account</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory1.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/sellertagndcategory1.webp" alt="image-31"></a></p><p>The seller will get the option to select category &amp; add tags on the seller signup page as well:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/06/image-30-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/06/image-30-1200x597.png" alt="image-30"></a></p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><p>Further, this how the sellers can be filtered based on categories &amp; tags:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/06/image-34-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/06/image-34-1200x597.png" alt="image-34"></a></p><p><strong>Note</strong>: In case you are using <strong>Theme 4</strong> for the seller profile page then please check <a href="https://webkul.uvdesk.com/en/blog/theme-4-code-for-seller-tags-categories" target="_blank" rel="noreferrer">this</a>.</p>',37)])])}const h=t(o,[["render",n]]);export{b as __pageData,h as default};
